insert into career_editorial_document_candidate(id,editorial_id,slug,template_id,locale,audience,title,lead,source_gate,human_gate,status) values ('DOC-CAREER-FIRST-SHIFT','ED-FIRST-SHIFT','meu-primeiro-plantao','TPL-POCKET-GUIDE-001','pt-BR','PROFESSIONAL','Meu Primeiro Plantão: um guia de preparação','O primeiro plantão não precisa ser uma prova de perfeição. Ele pode ser tratado como uma transição planejada: entender o contexto, reconhecer limites, pedir ajuda cedo e transformar cada turno em aprendizagem.','HOLD','HOLD','HOLD_HUMAN') on conflict(id) do update set title=excluded.title,lead=excluded.lead,source_gate=excluded.source_gate,human_gate=excluded.human_gate,status=excluded.status,updated_at=current_date;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-FIRST-SHIFT',1,'doc-career-first-shift-b1','section','body','Antes de chegar','Confirme horário, unidade, regras de acesso, uniforme e o que precisa levar. Organize deslocamento, alimentação e descanso com antecedência. O objetivo é reduzir decisões pequenas no dia e preservar atenção para o trabalho.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-FIRST-SHIFT',2,'doc-career-first-shift-b2','steps','core_sections','Durante o início do turno','','{"items":["Apresente-se e identifique quem é sua referência imediata.","Entenda a rotina da unidade antes de tentar acelerá-la.","Pergunte como a equipe organiza prioridades, registros e passagem de informações.","Quando não souber, diga que precisa confirmar antes de agir.","Anote dúvidas para revisar depois, sem registrar dados identificáveis de pacientes em materiais pessoais."]}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-FIRST-SHIFT',3,'doc-career-first-shift-b3','callout','safety','Seu limite também é uma competência','Pedir ajuda cedo é melhor do que esconder incerteza. Não assuma atribuições, procedimentos ou decisões para os quais você não está preparado, autorizado ou supervisionado conforme o contexto.','{}'::jsonb,'evidence','["SRC-CAREER-COFEN-LEI-7498-1986","SRC-CAREER-COFEN-RES-564-2017"]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-FIRST-SHIFT',4,'doc-career-first-shift-b4','section','body','Depois do plantão','Faça uma revisão curta: o que funcionou, onde você travou, que conhecimento precisa revisar e quem pode ajudar. Transforme uma experiência intensa em ações pequenas para o próximo turno.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-FIRST-SHIFT',5,'doc-career-first-shift-b5','references','references','Referências','Lei nº 7.498/1986 e Código de Ética dos Profissionais de Enfermagem. Consulte sempre as normas e protocolos aplicáveis ao seu contexto.','{}'::jsonb,'evidence','["SRC-CAREER-COFEN-LEI-7498-1986","SRC-CAREER-COFEN-RES-564-2017"]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_document_candidate(id,editorial_id,slug,template_id,locale,audience,title,lead,source_gate,human_gate,status) values ('DOC-CAREER-APPROVED','ED-APPROVED','fui-aprovado','TPL-ARTICLE-001','pt-BR','PROFESSIONAL','Fui aprovado. E agora?','A aprovação encerra uma seleção, mas abre uma nova etapa. Antes de transformar a conquista em pressa, organize documentos, expectativas, primeiros objetivos e a transição para o novo contexto.','HOLD','HOLD','HOLD_HUMAN') on conflict(id) do update set title=excluded.title,lead=excluded.lead,source_gate=excluded.source_gate,human_gate=excluded.human_gate,status=excluded.status,updated_at=current_date;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-APPROVED',1,'doc-career-approved-b1','section','body','Celebre e confira','Registre a conquista, mas leia com calma as orientações recebidas pela instituição: etapas seguintes, documentos, prazos, exames ou treinamentos exigidos. Não trate mensagem informal como substituta de comunicação oficial.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-APPROVED',2,'doc-career-approved-b2','steps','body','Prepare a entrada','','{"items":["Revise documentos e dados de cadastro solicitados pela instituição.","Confirme sua situação profissional perante o conselho quando o exercício exigir inscrição ativa.","Atualize seu passaporte profissional com a nova etapa.","Defina três objetivos para os primeiros 30 dias: integração, aprendizagem e segurança.","Evite comparar seu começo com o desempenho de quem já conhece a unidade há anos."]}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-APPROVED',3,'doc-career-approved-b3','callout','safety','Registro profissional','O exercício profissional de Enfermagem exige habilitação legal e inscrição no Conselho Regional competente. A situação concreta deve ser verificada no Coren da jurisdição de exercício.','{}'::jsonb,'evidence','["SRC-CAREER-COFEN-LEI-7498-1986","SRC-CAREER-COFEN-RES-769-2024"]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-APPROVED',4,'doc-career-approved-b4','section','body','Use a conquista como marco','Uma aprovação pode alimentar sua linha do tempo, portfólio e plano de carreira. O valor não está apenas no resultado, mas no que você aprendeu para chegar até ele e no que precisa desenvolver para sustentar a próxima fase.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-APPROVED',5,'doc-career-approved-b5','references','references','Referências','Lei nº 7.498/1986 e Resolução Cofen nº 769/2024, considerando as alterações indicadas pelo próprio Cofen.','{}'::jsonb,'evidence','["SRC-CAREER-COFEN-LEI-7498-1986","SRC-CAREER-COFEN-RES-769-2024"]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_document_candidate(id,editorial_id,slug,template_id,locale,audience,title,lead,source_gate,human_gate,status) values ('DOC-CAREER-VALUE','ED-VALUE','valorizacao-enfermagem','TPL-ARTICLE-001','pt-BR','PROFESSIONAL','Valorização profissional começa por tornar visível o que você sabe fazer','Valorização não é só reconhecimento externo. Ela também depende de como competências, responsabilidades, resultados, limites e desenvolvimento são documentados e comunicados.','PASS','HOLD','DRAFT_CANDIDATE') on conflict(id) do update set title=excluded.title,lead=excluded.lead,source_gate=excluded.source_gate,human_gate=excluded.human_gate,status=excluded.status,updated_at=current_date;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-VALUE',1,'doc-career-value-b1','section','body','Competência invisível quase sempre é subestimada','Muitas capacidades importantes aparecem diluídas na rotina: comunicação, priorização, educação, organização, segurança, trabalho em equipe e melhoria de processos. Registrar exemplos concretos ajuda a transformar experiência em linguagem profissional.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-VALUE',2,'doc-career-value-b2','steps','body','Torne sua trajetória legível','','{"items":["Registre competências e evidências no passaporte profissional.","Converta atividades em resultados observáveis, sem expor dados sensíveis.","Atualize currículo e portfólio a partir da mesma fonte canônica.","Use marcos para acompanhar crescimento ao longo do tempo.","Compare requisitos de oportunidades com suas evidências antes de assumir que está ''faltando tudo''."]}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-VALUE',3,'doc-career-value-b3','section','body','Valorização não é inflar o currículo','Não invente experiência, título ou domínio técnico. A credibilidade aumenta quando o documento deixa claro o que você fez, em que contexto, com que grau de autonomia e que evidência sustenta a afirmação.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-VALUE',4,'doc-career-value-b4','callout','note','Um princípio útil','Não tente parecer mais experiente do que é. Tente tornar mais compreensível o valor real da experiência que você já tem.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_document_candidate(id,editorial_id,slug,template_id,locale,audience,title,lead,source_gate,human_gate,status) values ('DOC-YOUTH-WHAT','ED-YOUTH-WHAT','o-que-faz-enfermagem','TPL-ARTICLE-001','pt-BR','YOUTH','O que a Enfermagem faz?','Enfermagem não é uma única função nem um único lugar de trabalho. É um campo profissional com diferentes níveis de formação, responsabilidades e possibilidades de atuação.','HOLD','HOLD','HOLD_HUMAN') on conflict(id) do update set title=excluded.title,lead=excluded.lead,source_gate=excluded.source_gate,human_gate=excluded.human_gate,status=excluded.status,updated_at=current_date;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-YOUTH-WHAT',1,'doc-youth-what-b1','section','body','Uma profissão ligada ao cuidado, à organização e à decisão','No Brasil, o exercício da Enfermagem é regulamentado. A legislação distingue categorias profissionais e respectivos graus de habilitação, e o exercício depende de habilitação legal e inscrição no Conselho Regional de Enfermagem competente.','{}'::jsonb,'evidence','["SRC-CAREER-COFEN-LEI-7498-1986","SRC-CAREER-COFEN-DEC-94406-1987"]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-YOUTH-WHAT',2,'doc-youth-what-b2','section','body','Onde a Enfermagem pode aparecer','Ao explorar a profissão, você pode encontrar contextos assistenciais, atenção primária, urgência, terapia intensiva, centro cirúrgico, gestão, auditoria, educação e pesquisa. Cada trajetória combina competências e requisitos diferentes; nenhuma lista curta representa todas as possibilidades.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-YOUTH-WHAT',3,'doc-youth-what-b3','comparison','body','Enfermeiro e Técnico de Enfermagem','São formações e habilitações diferentes, com atribuições diferentes definidas pela legislação. Não trate uma como ''versão menor'' da outra: compare formação, responsabilidades, rotina e caminho profissional antes de escolher.','{}'::jsonb,'evidence','["SRC-CAREER-COFEN-LEI-7498-1986","SRC-CAREER-COFEN-DEC-94406-1987"]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-YOUTH-WHAT',4,'doc-youth-what-b4','callout','note','Explorar não é decidir agora','Você pode começar conhecendo ambientes, conversando com profissionais, observando o que desperta curiosidade e comparando caminhos. Escolha informada costuma ser melhor do que escolha apressada.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-YOUTH-WHAT',5,'doc-youth-what-b5','references','references','Referências','Lei nº 7.498/1986 e Decreto nº 94.406/1987.','{}'::jsonb,'evidence','["SRC-CAREER-COFEN-LEI-7498-1986","SRC-CAREER-COFEN-DEC-94406-1987"]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_document_candidate(id,editorial_id,slug,template_id,locale,audience,title,lead,source_gate,human_gate,status) values ('DOC-YOUTH-FORMATION','ED-YOUTH-FORM','como-e-a-formacao','TPL-ARTICLE-001','pt-BR','YOUTH','Como funciona a formação em Enfermagem?','Existem caminhos formativos diferentes. Antes de comparar duração, preço ou instituição, entenda qual habilitação você quer construir e consulte as regras educacionais atuais.','HOLD','HOLD','HOLD_HUMAN') on conflict(id) do update set title=excluded.title,lead=excluded.lead,source_gate=excluded.source_gate,human_gate=excluded.human_gate,status=excluded.status,updated_at=current_date;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-YOUTH-FORMATION',1,'doc-youth-formation-b1','section','body','Graduação em Enfermagem','Em maio de 2026, o CNE instituiu novas Diretrizes Curriculares Nacionais para os cursos de Graduação em Enfermagem, bacharelado e licenciatura, revogando as diretrizes de 2001. As instituições devem organizar seus cursos conforme o marco educacional vigente.','{}'::jsonb,'evidence','["SRC-CAREER-MEC-DCN-ENF-2026"]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-YOUTH-FORMATION',2,'doc-youth-formation-b2','section','body','Formação técnica','A educação profissional técnica é organizada com referência no Catálogo Nacional de Cursos Técnicos do MEC. Como o catálogo passa por atualizações, consulte sempre a versão oficial vigente antes de usar carga horária, perfil ou requisitos como informação definitiva.','{}'::jsonb,'evidence','["SRC-CAREER-MEC-CNCT-2026"]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-YOUTH-FORMATION',3,'doc-youth-formation-b3','section','body','Formação e exercício profissional são camadas diferentes','Concluir uma formação não elimina as exigências legais para o exercício profissional. A legislação de Enfermagem e as normas administrativas de inscrição devem ser verificadas para a categoria e a jurisdição de exercício.','{}'::jsonb,'evidence','["SRC-CAREER-COFEN-LEI-7498-1986","SRC-CAREER-COFEN-RES-769-2024"]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-YOUTH-FORMATION',4,'doc-youth-formation-b4','steps','body','Antes de escolher um curso','','{"items":["Confirme se a instituição e o curso estão regulares nos sistemas oficiais aplicáveis.","Leia o perfil de formação e a matriz curricular, não apenas o nome do curso.","Pergunte como acontecem práticas, estágios e integração com serviços.","Compare custos totais, deslocamento e tempo disponível.","Verifique o caminho profissional que a formação habilita a construir."]}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-YOUTH-FORMATION',5,'doc-youth-formation-b5','references','references','Referências','Resolução CNE/CES nº 1/2026; CNCT/MEC; Lei nº 7.498/1986; Resolução Cofen nº 769/2024.','{}'::jsonb,'evidence','["SRC-CAREER-MEC-DCN-ENF-2026","SRC-CAREER-MEC-CNCT-2026","SRC-CAREER-COFEN-LEI-7498-1986","SRC-CAREER-COFEN-RES-769-2024"]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_document_candidate(id,editorial_id,slug,template_id,locale,audience,title,lead,source_gate,human_gate,status) values ('DOC-YOUTH-CHOICE','ED-YOUTH-CHOICE','como-explorar-areas','TPL-ARTICLE-001','pt-BR','YOUTH','Como explorar áreas da Enfermagem sem decidir cedo demais','Você não precisa escolher uma especialidade antes de conhecer a profissão. Primeiro construa repertório: contextos, atividades, competências, pessoas e perguntas.','PASS','HOLD','DRAFT_CANDIDATE') on conflict(id) do update set title=excluded.title,lead=excluded.lead,source_gate=excluded.source_gate,human_gate=excluded.human_gate,status=excluded.status,updated_at=current_date;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-YOUTH-CHOICE',1,'doc-youth-choice-b1','steps','body','Use quatro lentes','','{"items":["Contexto: em que tipo de ambiente o trabalho acontece?","Pessoas: com quem você interage e que tipo de colaboração é necessária?","Problemas: que situações precisam ser resolvidas?","Competências: o que você precisaria aprender e praticar para atuar ali?"]}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-YOUTH-CHOICE',2,'doc-youth-choice-b2','section','body','Interesse não é destino','Gostar de tecnologia, urgência, educação, pesquisa ou comunidade pode indicar temas para explorar, não uma resposta definitiva. Experiência muda preferências, e trajetórias profissionais podem combinar áreas diferentes ao longo do tempo.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-YOUTH-CHOICE',3,'doc-youth-choice-b3','reflection','body','Perguntas para conversar consigo mesmo','Em que situações eu gosto de aprender? Prefiro acompanhar processos ao longo do tempo ou lidar com mudanças rápidas? Gosto de explicar, investigar, organizar, executar, liderar ou combinar essas atividades?','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-YOUTH-CHOICE',4,'doc-youth-choice-b4','callout','note','Não transforme um quiz em sentença','Ferramentas de reflexão podem organizar perguntas, mas não substituem vivência, orientação educacional, conversa com profissionais e pesquisa sobre formação e trabalho.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_document_candidate(id,editorial_id,slug,template_id,locale,audience,title,lead,source_gate,human_gate,status) values ('DOC-CAREER-Y','ED-CAREER-Y','carreira-em-y','TPL-ARTICLE-001','pt-BR','PROFESSIONAL','Carreira em Y: especialização, liderança e caminhos híbridos','Crescer profissionalmente não significa obrigatoriamente virar gestor. Uma carreira pode aprofundar expertise, ampliar responsabilidade de liderança ou combinar os dois movimentos.','PASS','HOLD','DRAFT_CANDIDATE') on conflict(id) do update set title=excluded.title,lead=excluded.lead,source_gate=excluded.source_gate,human_gate=excluded.human_gate,status=excluded.status,updated_at=current_date;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-Y',1,'doc-career-y-b1','section','body','O que a ideia de Y ajuda a enxergar','Ela separa duas formas comuns de crescimento: aprofundar domínio especializado ou ampliar responsabilidade por pessoas, processos e decisões organizacionais. A realidade costuma ser menos simétrica: existem desvios, retornos e caminhos híbridos.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-Y',2,'doc-career-y-b2','comparison','body','Especialista e liderança','No caminho especialista, o foco tende a ser profundidade, domínio técnico, ensino, referência e resolução de problemas complexos. Na liderança, entram gestão de pessoas, priorização, qualidade, negociação e coordenação de sistemas. Nenhum caminho é automaticamente superior.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-Y',3,'doc-career-y-b3','steps','body','Escolha pelo próximo experimento, não pelo cargo final','','{"items":["Compare skills exigidas por cada caminho.","Observe que tipo de problema você quer aprender a resolver.","Busque experiências pequenas antes de uma transição grande.","Registre evidências do que aprendeu.","Revise a decisão periodicamente."]}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-Y',4,'doc-career-y-b4','callout','note','Carreira não precisa ser uma escada','Você pode alternar clínica, educação, pesquisa, gestão e projetos ao longo do tempo. O importante é preservar rastreabilidade das competências que cada etapa construiu.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_document_candidate(id,editorial_id,slug,template_id,locale,audience,title,lead,source_gate,human_gate,status) values ('DOC-CAREER-NEGOTIATION','ED-NEGOTIATION','negociacao-profissional','TPL-ARTICLE-001','pt-BR','PROFESSIONAL','Negociação e posicionamento profissional: prepare fatos antes da conversa','Negociação fica mais consistente quando você separa desejo, evidência, contexto e alternativas. O objetivo não é ''vencer'' a conversa; é torná-la clara.','PASS','HOLD','DRAFT_CANDIDATE') on conflict(id) do update set title=excluded.title,lead=excluded.lead,source_gate=excluded.source_gate,human_gate=excluded.human_gate,status=excluded.status,updated_at=current_date;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-NEGOTIATION',1,'doc-career-negotiation-b1','steps','body','Prepare quatro grupos de informação','','{"items":["Objetivo: o que você quer discutir?","Evidências: que entregas, competências ou responsabilidades sustentam sua posição?","Contexto: quais restrições ou critérios a instituição declarou?","Alternativas: o que você fará se a proposta não avançar agora?"]}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-NEGOTIATION',2,'doc-career-negotiation-b2','section','body','Evite argumentos vagos','''Eu mereço'' é difícil de avaliar. Prefira exemplos verificáveis de responsabilidade, escopo, desenvolvimento, resultados ou mudança de função. Quando houver dado de mercado, diferencie fonte oficial, salário anunciado, estimativa de pesquisa e índice.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-NEGOTIATION',3,'doc-career-negotiation-b3','section','body','Negociação também é ouvir','Pergunte quais critérios definem a decisão, que lacunas precisam ser fechadas e quando a conversa pode ser retomada. Uma resposta negativa pode virar informação para um plano de desenvolvimento.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-NEGOTIATION',4,'doc-career-negotiation-b4','callout','note','Mercado não é um único número','Use dados salariais como contexto, nunca como verdade universal. Localidade, jornada, vínculo, função e fonte mudam o significado do valor.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_document_candidate(id,editorial_id,slug,template_id,locale,audience,title,lead,source_gate,human_gate,status) values ('DOC-CAREER-FIRST-JOB','ED-FIRST-JOB','primeiro-emprego-enfermagem','TPL-ARTICLE-001','pt-BR','PROFESSIONAL','Primeiro emprego em Enfermagem: transforme a busca em um processo','Buscar o primeiro emprego fica menos caótico quando você separa preparação, oportunidades, candidaturas, entrevistas e aprendizagem. O objetivo não é mandar o maior número de currículos; é construir um processo que você consegue melhorar.','HOLD','HOLD','HOLD_HUMAN') on conflict(id) do update set title=excluded.title,lead=excluded.lead,source_gate=excluded.source_gate,human_gate=excluded.human_gate,status=excluded.status,updated_at=current_date;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-FIRST-JOB',1,'doc-career-first-job-b1','steps','body','Organize a jornada','','{"items":["Defina o tipo de oportunidade que você quer explorar primeiro.","Revise seu passaporte profissional e identifique competências com evidência.","Gere um currículo enxuto para o alvo escolhido.","Acompanhe candidaturas em um tracker.","Prepare exemplos para entrevistas.","Depois de cada processo, registre o que aprendeu."]}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-FIRST-JOB',2,'doc-career-first-job-b2','section','body','Sem experiência não significa sem evidência','Formação, estágios, projetos, monitorias, extensão, pesquisa, voluntariado, apresentações e responsabilidades acadêmicas podem ajudar a demonstrar competências. Descreva o que aconteceu de verdade; não converta exposição em domínio que você ainda não possui.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-FIRST-JOB',3,'doc-career-first-job-b3','callout','safety','Antes do exercício profissional','Verifique os requisitos legais e administrativos aplicáveis à sua categoria e à jurisdição onde ocorrerá o exercício. A legislação brasileira exige habilitação legal e inscrição no Conselho Regional competente.','{}'::jsonb,'evidence','["SRC-CAREER-COFEN-LEI-7498-1986","SRC-CAREER-COFEN-RES-769-2024"]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-FIRST-JOB',4,'doc-career-first-job-b4','section','body','Use rejeições como dado, não como identidade','Uma candidatura encerrada pode refletir timing, concorrência, requisito específico ou aderência ao perfil. Compare padrões ao longo de vários processos antes de concluir que o problema é ''você''.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
