insert into career_editorial_document_candidate(id,editorial_id,slug,template_id,locale,audience,title,lead,source_gate,human_gate,status) values ('DOC-CAREER-CV','ED-CV','curriculo-enfermagem','TPL-ARTICLE-001','pt-BR','PROFESSIONAL','Currículo de Enfermagem: transforme sua trajetória em informação clara','Um bom currículo não precisa parecer impressionante. Ele precisa permitir que outra pessoa entenda rapidamente quem você é profissionalmente, o que já fez e por que sua experiência é relevante para aquela oportunidade.','PASS','HOLD','DRAFT_CANDIDATE') on conflict(id) do update set title=excluded.title,lead=excluded.lead,source_gate=excluded.source_gate,human_gate=excluded.human_gate,status=excluded.status,updated_at=current_date;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-CV',1,'doc-career-cv-b1','section','body','Comece pela oportunidade','Antes de editar o documento, identifique o papel, requisitos e contexto. Depois selecione do seu passaporte profissional apenas as informações que ajudam a explicar aderência. O currículo é uma projeção da trajetória, não um arquivo mestre independente.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-CV',2,'doc-career-cv-b2','steps','body','Estrutura mínima útil','','{"items":["Resumo profissional coerente com seu estágio de carreira.","Formação e experiências relevantes.","Competências sustentadas por exemplos ou evidências.","Credenciais e cursos que façam sentido para o alvo.","Projetos, pesquisa, extensão ou voluntariado quando acrescentarem informação.","Dados de contato apenas no documento final destinado à candidatura, nunca no workspace candidato desta plataforma."]}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-CV',3,'doc-career-cv-b3','section','body','Escreva com evidência','Troque adjetivos por contexto. Em vez de ''excelente comunicação'', descreva onde essa competência apareceu. Em vez de ''domínio de UTI'' após uma experiência breve, use uma formulação proporcional ao que você realmente vivenciou.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-CV',4,'doc-career-cv-b4','callout','note','Uma fonte, várias projeções','Currículo, carta e portfólio devem nascer do mesmo passaporte profissional. Isso reduz versões contraditórias e facilita atualização.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
