insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-RESEARCH',3,'doc-career-research-b3','section','body','Carreira e pesquisa se alimentam','Projetos podem gerar skills e evidências para o passaporte profissional; gaps de carreira podem gerar perguntas de pesquisa. A integração deve acontecer por referências canônicas entre os domínios, não por cópia de dados.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-RESEARCH',4,'doc-career-research-b4','callout','note','Produção científica não é atalho de autoridade','Qualidade de método, transparência e responsabilidade importam mais do que acumular títulos ou publicações desconectadas.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_document_candidate(id,editorial_id,slug,template_id,locale,audience,title,lead,source_gate,human_gate,status) values ('DOC-CAREER-INTERNATIONAL','ED-INTERNATIONAL-START','carreira-internacional-primeiros-passos','TPL-ARTICLE-001','pt-BR','PROFESSIONAL','Carreira internacional: comece pela jurisdição, não pelo país dos sonhos','Trabalhar fora depende de regras específicas de reconhecimento, registro, idioma, imigração e empregador. Antes de gastar com cursos ou intermediários, organize a investigação por jurisdição.','PASS','HOLD','DRAFT_CANDIDATE') on conflict(id) do update set title=excluded.title,lead=excluded.lead,source_gate=excluded.source_gate,human_gate=excluded.human_gate,status=excluded.status,updated_at=current_date;
