insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-INTERNATIONAL',2,'doc-career-international-b2','section','body','Não copie requisitos de outro país','Mesmo países com sistemas de saúde semelhantes podem exigir processos diferentes. Requisitos mudam com o tempo; por isso o banco de Carreira Internacional mantém cada regra ligada à jurisdição, fonte e validade.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_json,source_mode,source_refs_json) values ('DOC-CAREER-INTERNATIONAL',3,'doc-career-international-b3','section','body','Prepare o que é transferível','Idioma, documentação organizada, portfólio de competências, experiência bem descrita e hábitos de verificação ajudam em várias rotas, mesmo quando as exigências regulatórias são diferentes.','{}'::jsonb,'static_nontechnical_copy','[]'::jsonb) on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_json=excluded.payload_json,source_mode=excluded.source_mode,source_refs_json=excluded.source_refs_json;
